import{_ as t,o as a,c as s,ae as o}from"./chunks/framework.Dn6zxbF8.js";const c=JSON.parse('{"title":"mise","description":"","frontmatter":{"name":"mise","quadrant":"tools","history":[{"edition":"2026.2","ring":"adopt"}],"tags":["developer-experience","task-runner","toolchain"]},"headers":[],"relativePath":"radar/items/mise.md","filePath":"radar/items/mise.md"}'),i={name:"radar/items/mise.md"};function n(r,e,d,h,p,m){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="mise" tabindex="-1">mise <a class="header-anchor" href="#mise" aria-label="Permalink to &quot;mise&quot;">​</a></h1><p>mise is the entrypoint into a repository. It pins the toolchain a project needs, exposes the tasks that operate on it, loads the environment those tasks run with, and decrypts the secrets they read. One tool, one config, checked in next to the code.</p><p>The reason it sits in Adopt is not that it runs tasks well. It is that the task and the toolchain the task depends on stop being two separate promises. A task declared in <code>.config/mise/tasks</code> runs against the versions declared in the same configuration, so <code>mise run</code> on a laptop and in CI is the same execution, and a contributor who cloned the repository five minutes ago is not the person who discovers the version drift.</p><p>Secrets follow the same reasoning. mise reads <a href="./sops.html">SOPS</a>-encrypted files as environment, so decryption is part of entering the project rather than a step every task has to remember to perform.</p><p>This is what replaced <a href="./task.html">Task</a>, <a href="./ejson.html">EJSON</a>, and <a href="./direnv.html">direnv</a>, and all three of those blips are on Hold because of it.</p><p>Adopting a tool is also a bet that it will still be maintained in three years. That bet reads better than it did: Omarchy ships mise as its developer runtime manager, and the Omacom Foundation behind it is a premier sponsor of the project. A tool with a distribution depending on it is a different risk profile from a tool with one maintainer and a good README.</p>',6)])])}const f=t(i,[["render",n]]);export{c as __pageData,f as default};
